 if(modal.type==='trade'){const merchant=modal.merchant,name=MERCHANTS[merchant].name,v=state[merchant]?.visit,offer=v?.offers?.[modal.offer];if(!offer){close();return;}return modalShell(v.role==='seller'?'Договориться о покупке':'Договориться о продаже',`<div class="row"><div class="item-icon">${icon(ITEMS[offer.item].icon)}</div><div><h3>${esc(itemName(offer))}</h3><p class="subtitle">${offer.qty} шт. · ${v.role==='seller'?'ты платишь '+name:name+' платит тебе'}</p></div></div><p class="note">${v.role==='seller'?'Заплатишь больше — торговец получит больше опыта и вернётся быстрее.':'Продашь дешевле — торговец получит больше опыта и вернётся быстрее.'}</p><div class="trade-grid">${TRADE_MODIFIERS.map(m=>{const q=tradeQuote(offer,offer.qty,m,v.role,merchant,state);return `<button class="trade-button ${m===0?'default':''}" data-action="trade" data-modifier="${m}" ${(v.role==='seller'?state.money<q.price:tradeQuote(offer,offer.qty,0,'buyer',merchant,state).price>(v.buyBudget??300*state[merchant].level*(MERCHANTS[merchant].budgetMultiplier??1)))?'disabled':''}><b>${m>0?'+':''}${m}%</b><strong>${money(q.price)} A</strong><small>${num(q.cooldown/1000)} сек. · +${num(q.xp)} XP</small></button>`;}).join('')}</div><p class="note">Выбери цену для завершения сделки. </p><button class="linkbutton" data-action="yuras" data-merchant="${merchant}">Вернуться к товарам</button>`);}
