 if(modal.type==='about')return modalShell('Сохранение и игра',`<p class="note">Автозаводская: отправляй сталкеров на локации, развивай производство и торгуй находками.</p><dl class="about-list"><dt>Сохранение</dt><dd>${storageWorks?'В этом браузере автоматически':'Недоступно — экспортируй вручную'}</dd><dt>При закрытии</dt><dd>Таймеры продолжаются</dd><dt>Обновление</dt><dd>${esc(CHANGELOG[0].label)}</dd></dl><hr class="divider"><div class="button-row">${btn('Скачать сохранение','export','','secondary')}${btn('Загрузить','import','','ghost')}${btn('Версии','versions','','secondary')}</div><input type="file" id="import-save" accept="application/json,.json" hidden><hr class="divider"><button class="linkbutton red" data-action="newGameAsk">Всё сначала</button>`);
