let previousReady='';
function tick(){if(advanceSeries(state)){save();render();}if(visit(state)){save();render();}const jobs=[...getHeroes(state).map(x=>x.job),...Object.values(state.productions).map(p=>p.job),...state.shelves].filter(Boolean);const key=jobs.map(x=>`${x.endsAt}:${ready(x)}`).join('|');if(key!==previousReady&&!hold){previousReady=key;render();}document.querySelectorAll('[data-until]').forEach(el=>{const at=Number(el.dataset.until);el.textContent=ready({endsAt:at})?(el.dataset.readyLabel??'Готово'):`${sec(at)} сек.`;});document.querySelectorAll('[data-progress]').forEach(el=>{const [start,end]=el.dataset.progress.split(',').map(Number);el.style.width=`${Math.min(100,(Date.now()-start)/(end-start)*100)}%`;});}
